UFunction* BasicFilesImplUtils::FindFunctionByFName(const FName* Name)
{
	for (int i = 0; i < InSDKUtils::GetGObjects()->Num(); ++i)
	{
		UObject* Object = InSDKUtils::GetObjectByIndex(i);

		if (!Object)
			continue;

		if (Object->Name == *Name)
			return static_cast<UFunction*>(Object);
	}

	return nullptr;
}

